 private void render(){final int targetScroll=scrollY;DisplayOptions o=DisplayOptions.load(this);o.theme=draft.theme;dark=!new Palette(this,o).light;ink=dark?0xFFF1F5FA:0xFF172C40;muted=dark?0xFFB5C8D8:0xFF4C6175;bg=dark?0xFF101820:0xFFF2F5F8;panel=dark?0xFF202F3D:0xFFFFFFFF;
  LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setLayoutDirection(en()?View.LAYOUT_DIRECTION_LTR:View.LAYOUT_DIRECTION_RTL);root.setBackgroundColor(bg);root.setPadding(dp(48),dp(26),dp(48),dp(24));
  TextView heading=text(t("إعداد سريع","Quick setup"),30,ink);root.addView(heading,new LinearLayout.LayoutParams(-1,dp(54)));
  LinearLayout body=new LinearLayout(this);body.setGravity(Gravity.CENTER_VERTICAL);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));
  ScrollView scroll=new ScrollView(this);scroll.setVerticalScrollBarEnabled(false);body.addView(scroll,new LinearLayout.LayoutParams(-1,-1));controls=new LinearLayout(this);controls.setOrientation(LinearLayout.VERTICAL);controls.setPadding(dp(4),dp(8),dp(4),dp(8));scroll.addView(controls);scroll.setOnScrollChangeListener((v,x,y,ox,oy)->scrollY=y);
  if(draft.step==0){
   LinearLayout previews=new LinearLayout(this);previews.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);controls.addView(previews,new LinearLayout.LayoutParams(-1,dp(212)));
   for(boolean simple:new boolean[]{false,true}){StylePreview preview=new StylePreview(simple);LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(0,-1,1);pp.setMargins(dp(4),0,dp(4),dp(10));previews.addView(preview,pp);}
   LinearLayout location=new LinearLayout(this);location.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);controls.addView(location,new LinearLayout.LayoutParams(-1,dp(54)));
   TextView country=button(t("الدولة · ","Country · ")+(draft.country.isEmpty()?t("اختر الدولة","Choose country"):new Locale("",draft.country).getDisplayCountry(new Locale(draft.language))),this::countries);
   TextView city=button(t("المدينة · ","City · ")+(draft.prayerPlace==null||!draft.country.equals(draft.prayerPlace.country)?t("اختيار مطلوب","Required"):place(draft.prayerPlace)),()->pick(false));
   for(TextView v:new TextView[]{country,city}){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(48),1);lp.setMargins(dp(4),0,dp(4),0);location.addView(v,lp);}
   add(t("إعدادات متقدمة · ","Advanced settings · ")+(draft.advanced?t("إخفاء","Hide"):t("اختياري","Optional")),()->{draft.advanced=!draft.advanced;scrollY=0;render();});
   if(draft.advanced){
    add(t("لغة الإعداد · العربية","Setup language · English"),()->{draft.language=en()?"ar":"en";render();});
    add(t("المظهر · ","Appearance · ")+("light".equals(draft.theme)?t("فاتح","Light"):"auto".equals(draft.theme)?t("تلقائي","Auto"):t("داكن","Dark")),()->{draft.theme="light".equals(draft.theme)?"dark":"light";render();});
    if(draft.focused())add(t("لون الخلفية · ","Background color · ")+(draft.focusColor.equals("white")?t("أبيض","White"):draft.focusColor.equals("black")?t("أسود","Black"):t("أزرق","Blue")),()->{draft.focusColor=draft.focusColor.equals("blue")?"white":draft.focusColor.equals("white")?"black":"blue";render();});
    add(t("مواقيت الصلاة · ","Prayer times · ")+(draft.prayers?t("تشغيل","On"):t("متوقفة","Off")),()->{draft.prayers=!draft.prayers;render();});
    if(draft.prayerPlace!=null){add(t("طريقة الصلاة · ","Prayer method · ")+draft.prayerPlace.label(en()),()->pick(false,true));add(t("الإحداثيات والمنطقة الزمنية","Coordinates and time zone"),this::coordinates);}
    if(draft.focused())note(t("الوضع البسيط: الساعة والصلاة فقط، دون طقس أو مباريات.","Simple mode: clock and prayer times only; no weather or matches."));
    else {add(t("الطقس · ","Weather · ")+(draft.weather?t("تشغيل","On"):t("متوقف","Off")),()->{draft.weather=!draft.weather;render();});if(draft.weather){add(t("مدينة الطقس · ","Weather city · ")+(draft.separateWeather?t("مستقلة","Separate"):t("نفس المدينة","Same city")),()->{draft.separateWeather=!draft.separateWeather;if(!draft.separateWeather)draft.weatherPlace=draft.prayerPlace;render();});if(draft.separateWeather)add(t("اختيار مدينة الطقس · ","Choose weather city · ")+place(draft.weatherPlace),()->pick(true));}}
    note(t("تنبيهات الصلاة وأزرار الريموت تبقى كما اخترتها.","Prayer reminders and remote buttons keep your settings."));
   }
  }else{
   note(t("لا تُحفظ التغييرات إلا عند الضغط على حفظ.","Changes are saved only when you choose Save."));
   summary(t("النمط","Style"),draft.focused()?t("بسيط · أرقام إنجليزية · ساعة وصلاة فقط","Simple · English numerals · clock and prayer times"):t("صور المدن · أرقام عربية","City photos · Arabic numerals"));
   summary(t("الدولة والمدينة","Country and city"),new Locale("",draft.country).getDisplayCountry(new Locale(draft.language))+" · "+place(draft.prayerPlace));
   summary(t("الصلاة","Prayer times"),draft.prayers?draft.prayerPlace.label(en()):t("متوقفة","Off"));
   if(!draft.focused())summary(t("الطقس","Weather"),draft.weather?(draft.separateWeather?place(draft.weatherPlace):t("نفس المدينة","Same city")):t("متوقف","Off"));
   note(t("يمكنك الرجوع لتعديل اختيارك قبل الحفظ.","Go back to adjust your choices before saving."));
  }
  message=text("",14,dark?0xFFFFD89A:0xFF8A4800);controls.addView(message);
  LinearLayout footer=new LinearLayout(this);footer.setGravity(Gravity.CENTER_VERTICAL);root.addView(footer,new LinearLayout.LayoutParams(-1,-2));TextView back=button(t("رجوع","Back"),this::onBackPressed),skip=button(t("تخطّي دون تغييرات","Skip without changes"),this::leave),next=button(draft.step==0?t("مراجعة","Review"):t("حفظ وابدأ","Save and start"),()->{if(draft.step==0){try{draft.payload();draft.step=1;scrollY=0;render();}catch(IllegalArgumentException e){message.setText(t("اختر الدولة، ثم مدينة أو منطقة منها.","Choose a country, then a city or area in it."));}}else save();});for(TextView v:new TextView[]{back,skip,next}){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(dp(4),0,dp(4),0);footer.addView(v,p);}
  setContentView(root);scroll.post(()->scroll.scrollTo(0,targetScroll));if(focusIndex<0)controls.getChildAt(0).requestFocus();else if(focusIndex>=controls.getChildCount()||!controls.getChildAt(focusIndex).requestFocus())next.requestFocus();
 }
 private void summary(String label,String value){TextView v=text(label+"\n"+value,18,ink);v.setPadding(dp(16),dp(12),dp(16),dp(12));controls.addView(v);}
 private void countries(){ArrayList<String> codes=new ArrayList<>();for(String c:Locale.getISOCountries())if(ContentPolicy.country(c))codes.add(c);Locale locale=new Locale(draft.language);codes.sort((a,b)->new Locale("",a).getDisplayCountry(locale).compareTo(new Locale("",b).getDisplayCountry(locale)));for(String c:new String[]{"EG","SA","KW"}){codes.remove(c);codes.add(0,c);}String[] names=new String[codes.size()];for(int i=0;i<names.length;i++)names[i]=new Locale("",codes.get(i)).getDisplayCountry(locale);new AlertDialog.Builder(this).setTitle(t("الدولة","Country")).setItems(names,(d,n)->{draft.country(codes.get(n));render();}).show();}
 private void pick(boolean weather){pick(weather,false);}
 private void pick(boolean weather,boolean details){if(draft.country.isEmpty()){message.setText(t("اختر الدولة أولًا، أو تخطَّ الإعداد.","Choose a country first, or skip setup."));return;}Place p=weather?draft.weatherPlace:draft.prayerPlace;if(p==null)p=new Place(draft.country,t("اختر المدينة","Choose city"),0,0,java.time.ZoneId.systemDefault().getId(),Place.methodFor(draft.country),false,false,true);startActivityForResult(new Intent(this,LocationPickerActivity.class).putExtra("place",p.json()).putExtra("country",draft.country).putExtra("weatherOnly",weather).putExtra("cityOnly",!details).putExtra("language",draft.language).putExtra("unselected",p.needsConfirmation),weather?42:41);}
 private void coordinates(){Place p=draft.prayerPlace;if(p==null)return;LinearLayout form=new LinearLayout(this);form.setPadding(dp(20),dp(8),dp(20),dp(8));form.setOrientation(LinearLayout.VERTICAL);EditText[] fields=new EditText[4];String[] labels={t("اسم المدينة","City name"),t("خط العرض","Latitude"),t("خط الطول","Longitude"),t("المنطقة الزمنية، مثل Asia/Riyadh","Time zone, e.g. Asia/Riyadh")};String[] values={p.name,Double.toString(p.lat),Double.toString(p.lon),p.zone};for(int i=0;i<4;i++){fields[i]=new EditText(this);fields[i].setSingleLine();fields[i].setHint(labels[i]);fields[i].setText(values[i]);fields[i].setContentDescription(labels[i]);form.addView(fields[i]);}AlertDialog dialog=new AlertDialog.Builder(this).setTitle(t("موقع الصلاة","Prayer location")).setView(form).setPositiveButton(t("استخدام","Use"),null).setNegativeButton(t("إلغاء","Cancel"),null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{try{draft.city(new Place(p.country,fields[0].getText().toString(),Double.parseDouble(fields[1].getText().toString()),Double.parseDouble(fields[2].getText().toString()),fields[3].getText().toString(),p.method,p.hanafi,p.manualMethod,false));dialog.dismiss();render();}catch(Exception invalid){fields[1].setError(t("تحقق من الإحداثيات والمنطقة الزمنية","Check coordinates and time zone"));}}));dialog.show();}
 private void save(){try{String payload=draft.payload();ContentValues values=new ContentValues();values.put("quickSetup",payload);if(getContentResolver().update(DisplayOptions.URI,values,null,null)!=1)throw new IllegalStateException();Dock.prefs(this).edit().putBoolean("setup_complete",true).putBoolean("quick_setup_seen",true).apply();leave();}catch(IllegalArgumentException missing){draft.step=0;draft.advanced=true;render();message.setText(t("اختر الدولة، ثم مدينة أو منطقة منها.","Choose a country, then a city or area in it."));}catch(Exception e){message.setText(t("لم تُحفظ التغييرات. تأكد من وجود التطبيق المرافق وحاول مجددًا.","Could not save. Check the companion app and try again."));}}
 private void leave(){Dock.prefs(this).edit().putBoolean("quick_setup_seen",true).apply();startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP));finish();}
 @Override public void onBackPressed(){if(draft.step==1){draft.step=0;scrollY=0;render();}else leave();}
 @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(result==RESULT_OK&&data!=null)try{Place p=Place.parse(data.getStringExtra("place"));if(code==42)draft.weatherPlace=p;else if(code==41){draft.country(p.country);draft.city(p);}render();}catch(Exception ignored){}}
 private Bitmap previewPhoto;
 @Override protected void onDestroy(){if(previewPhoto!=null){previewPhoto.recycle();previewPhoto=null;}super.onDestroy();}
 private class StylePreview extends View {
  final boolean simple;final Paint p=new Paint(3);final kw.urtv.shared.SimplePrayerFace face;final DisplayOptions opt;final Palette colors;
  StylePreview(boolean simple){super(SetupActivity.this);this.simple=simple;opt=DisplayOptions.load(SetupActivity.this);opt.surface=simple?"focus":"scenic";opt.latin=simple;opt.focusColor=draft.focusColor;opt.prayersEnabled=true;colors=new Palette(SetupActivity.this,opt);face=new kw.urtv.shared.SimplePrayerFace(SetupActivity.this);setFocusable(true);setClickable(true);setDefaultFocusHighlightEnabled(false);setContentDescription(simple?t("بسيط · ساعة وصلاة · أرقام إنجليزية","Simple · clock and prayers · English numerals"):t("صور المدن · أرقام عربية","City photos · Arabic numerals"));setOnFocusChangeListener((v,f)->invalidate());setSelected(draft.focused()==simple);setOnClickListener(v->{draft.surface=simple?"focus":"scenic";focusIndex=0;for(int i=0;i<((ViewGroup)getParent()).getChildCount();i++){View child=((ViewGroup)getParent()).getChildAt(i);child.setSelected(((StylePreview)child).simple==draft.focused());child.invalidate();}});if(!simple&&previewPhoto==null)try(java.io.InputStream in=getAssets().open("wallpapers/sunset.jpg")){BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=8;previewPhoto=BitmapFactory.decodeStream(in,null,o);}catch(Exception ignored){} }
  private void previewText(Canvas c,String s,float x,float y,float size){p.setColor(0xFFF1F5FA);p.setTypeface(font);p.setTextSize(size);p.setTextAlign(Paint.Align.CENTER);c.drawText(s,x,y,p);}
  private void scenic(Canvas c,float w,float h){c.save();c.scale(w/960f,h/540f);p.setColor(0x85101D2D);c.drawRoundRect(30,40,330,440,14,14,p);previewText(c,"مواقيت الصلاة · معاينة",180,70,17);String[] names={"الفجر","الشروق","الظهر","العصر","المغرب","العشاء"};int[] times={280,360,690,900,1020,1110};TimeTiles.GlassPainter tile=new TimeTiles.GlassPainter();for(int i=0;i<6;i++){previewText(c,names[i],280,124+i*55,18);tile.draw(c,TimeTiles.clock(times[i],opt),TimeTiles.period(times[i],opt),44,96+i*55,176,42,font,0xFFF1F5FA,.68f,false,false,true);}previewText(c,"٣:٢٠",740,142,84);previewText(c,"السبت، ٢٤ أكتوبر",740,188,18);previewText(c,"الطقس حسب مدينتك",740,250,24);previewText(c,"التالي · المغرب",806,330,18);previewText(c,"الوقت المتبقي",650,330,18);tile.draw(c,"٠٥:٠٠","م",736,350,160,42,font,0xFFF1F5FA,.68f,false,false,true);tile.draw(c,"٠١:٤٠","",570,350,160,42,font,0xFFF1F5FA,.68f,false,false,true);c.restore();}
  @Override protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();boolean chosen=draft.focused()==simple;
   p.setStyle(Paint.Style.FILL);p.setColor(panel);c.drawRoundRect(3,3,w-3,h-3,dp(12),dp(12),p);
   c.save();c.clipRect(dp(10),dp(10),w-dp(10),h-dp(45));c.translate(dp(10),dp(10));float pw=w-dp(20),ph=h-dp(55);
   if(simple){FocusBackdrop backdrop=new FocusBackdrop(opt.focusColor);backdrop.setBounds(0,0,(int)pw,(int)ph);backdrop.draw(c);}
   else {if(previewPhoto!=null)c.drawBitmap(previewPhoto,null,new RectF(0,0,pw,ph),p);c.drawColor(0x66101D2D);}
   java.time.ZonedDateTime sample=java.time.ZonedDateTime.of(2026,10,24,15,20,0,0,java.time.ZoneId.of("Asia/Kuwait"));
   if(simple)face.draw(c,pw,ph,opt,colors,sample,t("معاينة","Preview"),new int[]{280,360,690,900,1020,1110},new int[]{280,360,690,900,1020,1110},sample.toLocalDate(),new int[]{281,361,690,900,1020,1110});else scenic(c,pw,ph);c.restore();
   p.setTypeface(font);p.setTextAlign(Paint.Align.RIGHT);p.setTextSize(dp(16));p.setColor(ink);c.drawText((chosen?"✓  ":"")+(simple?t("بسيط · أرقام إنجليزية","Simple · English numerals"):t("صور المدن · أرقام عربية","City photos · Arabic numerals")),w-dp(18),h-dp(16),p);
   p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(isFocused()?3:chosen?2:0));p.setColor(isFocused()?ink:chosen?muted:Color.TRANSPARENT);c.drawRoundRect(3,3,w-3,h-3,dp(12),dp(12),p);p.setStyle(Paint.Style.FILL);
  }
 }
